import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.F7eQ-ohH.js";const n="/bzygq/assets/89f36107c821412cabc58b39498fa827.Chmyx0jL.png",i="/bzygq/assets/1589577e86524fc18286088cd4859cbc.BiMveqU4.png",p="/bzygq/assets/f8915e46feac4b44b37751e7687a4d28.DqCOi8-G.png",d="/bzygq/assets/da3f87b6e3e84372a6263c2e342bf775.stoNg8O4.png",m=JSON.parse('{"title":"02-SpringBoot工程启动与自动配置","description":"","frontmatter":{},"headers":[],"relativePath":"Java面试问题汇总/Spring、Spring Boot、Spring Cloud/02-SpringBoot工程启动与自动配置.md","filePath":"Java面试问题汇总/Spring、Spring Boot、Spring Cloud/02-SpringBoot工程启动与自动配置.md","lastUpdated":1788929995000}'),l={name:"Java面试问题汇总/Spring、Spring Boot、Spring Cloud/02-SpringBoot工程启动与自动配置.md"};function s(c,t,h,u,g,b){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="_02-springboot工程启动与自动配置" tabindex="-1">02-SpringBoot工程启动与自动配置 <a class="header-anchor" href="#_02-springboot工程启动与自动配置" aria-label="Permalink to &quot;02-SpringBoot工程启动与自动配置&quot;">​</a></h1><p>Spring Boot 是建立在 Spring Framework 之上的工程启动、依赖治理、默认装配和运行观测体系。它不替代 Spring Framework 的 IoC、AOP、事务、MVC、数据访问等底层能力，而是把这些能力按照常见业务场景重新组织成一套更容易创建、启动、配置、部署和排查的工程模型。</p><p>面试里谈 Spring Boot，不能只背“约定优于配置”和“开箱即用”。这两个词只能说明体验，不能说明机制。更完整的表达应该是：Starter 负责把某个开发场景需要的依赖和版本组合放进 classpath；自动配置负责在 classpath、配置属性、运行环境和已有 Bean 满足条件时注册默认组件；外部化配置负责把不同环境差异从代码中剥离；内嵌 Servlet 容器负责让 Web 应用脱离外部 Tomcat 独立启动；Actuator 和日志、指标、健康检查负责支撑线上观测。把这几件事串起来，才是真正的 Spring Boot 工程启动链路。</p><p>复习这一章时，要形成三种能力：第一，能讲清 Spring Boot 和 Spring Framework 的边界，避免把 Boot 说成一个“新 Spring”；第二，能沿着源码入口讲出自动配置为什么生效、为什么失效、怎样覆盖；第三，能把 REST 接口、校验、异常、定时、异步、线程池、Actuator 等工程能力连接到真实项目表达，而不是停留在注解清单。</p><h2 id="一、spring-boot-的工程装配价值" tabindex="-1">一、Spring Boot 的工程装配价值 <a class="header-anchor" href="#一、spring-boot-的工程装配价值" aria-label="Permalink to &quot;一、Spring Boot 的工程装配价值&quot;">​</a></h2><h3 id="_1-spring-framework-提供能力-spring-boot-组织能力" tabindex="-1">1. Spring Framework 提供能力，Spring Boot 组织能力 <a class="header-anchor" href="#_1-spring-framework-提供能力-spring-boot-组织能力" aria-label="Permalink to &quot;1\\. Spring Framework 提供能力，Spring Boot 组织能力&quot;">​</a></h3><p>Spring Framework 的核心职责是提供基础编程模型：IoC 容器负责对象创建和依赖注入，AOP 负责横切逻辑增强，事务抽象负责统一事务边界，Spring MVC 负责 Web 请求分发，数据访问模块负责屏蔽 JDBC、ORM、事务管理等细节。也就是说，只使用 Spring Framework 也完全可以写 Web、事务、缓存、消息、数据库项目。</p><p>传统 Spring 项目的痛点不在于“功能做不到”，而在于“每次都要重新装配”。例如启用 Spring MVC，要自己配置 DispatcherServlet、HandlerMapping、HandlerAdapter、消息转换器、静态资源映射和异常处理；接入数据库，要自己选择连接池、声明 DataSource、事务管理器、JdbcTemplate 或 ORM 相关 Bean；引入 JSON、校验、日志、监控时，还要处理依赖版本之间是否兼容。项目规模不大时，这些配置只是繁琐；项目多了以后，它会变成重复劳动、版本冲突和启动不稳定的来源。</p><p>Spring Boot 的定位就是把这类重复工程装配沉淀为框架约定。它不是取消配置，而是先给出大多数场景下合理的默认配置，再允许开发者通过配置属性、自定义 Bean、排除自动配置、扩展回调等方式精确覆盖。这个边界在面试里非常关键：Spring 是能力底座，Boot 是工程脚手架和运行时封装；Spring 解决“能不能做”，Boot 解决“怎样低成本、可维护地做”。</p><p><img src="'+n+'" alt="images/02-springboot-capability-map.png"></p><p>images/02-springboot-capability-map.png</p><h3 id="_2-boot-的五类工程价值要分层表达" tabindex="-1">2. Boot 的五类工程价值要分层表达 <a class="header-anchor" href="#_2-boot-的五类工程价值要分层表达" aria-label="Permalink to &quot;2\\. Boot 的五类工程价值要分层表达&quot;">​</a></h3><p>Spring Boot 的能力可以拆成五层。第一层是依赖聚合，也就是 Starter 把常见场景需要的库组合好，并依托 Boot 的依赖管理控制版本。第二层是自动配置，也就是根据条件注册默认 Bean，减少重复配置。第三层是外部化配置，也就是把端口、数据源、缓存地址、开关、日志级别等运行参数放到配置源中，而不是写死在代码里。第四层是内嵌容器，也就是让 Web 应用以可执行 JAR 方式独立运行。第五层是运行观测，也就是 Actuator、健康检查、指标、映射、Bean、配置等信息帮助排查线上问题。</p><table tabindex="0"><thead><tr><th>能力层</th><th>解决的问题</th><th>面试表达重点</th></tr></thead><tbody><tr><td>Starter</td><td>依赖怎么选，版本怎么兼容</td><td>它是场景化依赖集合，不等同于自动配置</td></tr><tr><td>自动配置</td><td>默认 Bean 由谁创建</td><td>根据 classpath、属性、已有 Bean、运行环境等条件判断</td></tr><tr><td>外部化配置</td><td>不同环境参数如何切换</td><td>最终值来自 Environment，不只来自 application.yml</td></tr><tr><td>内嵌容器</td><td>Web 应用如何独立运行</td><td>从部署 WAR 到运行可执行 JAR，容器成为应用进程的一部分</td></tr><tr><td>Actuator</td><td>线上状态如何观测</td><td>健康、指标、Bean、映射、配置、日志等端点要有安全边界</td></tr></tbody></table><p>面试官如果问“Spring Boot 有什么优点”，不要只列“快速开发、开箱即用、减少 XML”。这些说法太浅。更好的回答是：Boot 把 Spring 应用的依赖选择、默认 Bean 装配、配置覆盖、运行方式和观测能力做成统一工程约定，降低项目初始化和多环境部署成本，同时保留 Spring Framework 的扩展能力。这个回答能继续接自动配置源码、Starter 原理、配置优先级和线上排查。</p><h3 id="_3-spring-boot-的适用边界" tabindex="-1">3. Spring Boot 的适用边界 <a class="header-anchor" href="#_3-spring-boot-的适用边界" aria-label="Permalink to &quot;3\\. Spring Boot 的适用边界&quot;">​</a></h3><p>Spring Boot 的默认配置服务于通用场景，不等于适合所有系统。比如默认 JSON 序列化策略、默认线程池、默认错误响应、默认静态资源映射、默认健康检查细节，在中大型项目里经常需要调整。再比如引入某个 Starter 后，classpath 发生变化，可能触发某些自动配置；如果团队不了解条件装配逻辑，就容易出现“为什么突然多了一个 Bean”“为什么自定义配置不生效”的问题。</p><p>因此在项目表达中要强调两点：第一，Boot 的默认配置是起点，不是终点；第二，生产项目必须知道如何覆盖默认行为。覆盖方式通常有四种：改配置项、声明同类型或指定名称的 Bean、实现框架扩展接口、排除某个自动配置类。能讲清这四种方式，说明你不是只会用注解，而是理解 Boot 的工程边界。</p><h2 id="二、starter-的依赖聚合、版本管理与自动配置触发条件" tabindex="-1">二、Starter 的依赖聚合、版本管理与自动配置触发条件 <a class="header-anchor" href="#二、starter-的依赖聚合、版本管理与自动配置触发条件" aria-label="Permalink to &quot;二、Starter 的依赖聚合、版本管理与自动配置触发条件&quot;">​</a></h2><h3 id="_1-starter-的依赖组合职责" tabindex="-1">1. Starter 的依赖组合职责 <a class="header-anchor" href="#_1-starter-的依赖组合职责" aria-label="Permalink to &quot;1\\. Starter 的依赖组合职责&quot;">​</a></h3><p>Starter 是面向场景的依赖集合。它本身通常不写大量业务代码，而是把某类开发场景需要的库按兼容版本组合起来。例如 spring-boot-starter-web 会引入 Spring MVC、Jackson、校验相关基础、日志桥接以及默认内嵌 Tomcat；spring-boot-starter-jdbc 会引入 JDBC、连接池和事务基础；spring-boot-starter-data-redis 会引入 Spring Data Redis、客户端和序列化相关依赖。</p><p>这里最容易混淆的是：Starter 把依赖放进 classpath，自动配置根据 classpath 和条件注册 Bean。两者经常一起出现，但不是同一件事。以 Web 项目为例，引入 spring-boot-starter-web 后，classpath 里出现 Spring MVC、Jackson、Servlet 容器相关类；随后 Web MVC 自动配置类、Jackson 自动配置类、Servlet 容器自动配置类的条件开始满足，框架才会创建消息转换器、错误处理、静态资源处理、DispatcherServlet 注册等默认组件。Starter 是“把材料放上桌”，自动配置是“判断要不要做成菜”。</p><table tabindex="0"><thead><tr><th>对比项</th><th>Starter</th><th>自动配置</th></tr></thead><tbody><tr><td>关注点</td><td>依赖聚合和版本协调</td><td>Bean 注册和属性绑定</td></tr><tr><td>触发位置</td><td>构建阶段进入依赖树</td><td>应用启动时进入容器刷新流程</td></tr><tr><td>典型文件</td><td>pom.xml、Gradle dependencies</td><td>.imports、自动配置类、条件注解</td></tr><tr><td>常见问题</td><td>依赖冲突、重复引入、版本不匹配</td><td>条件不满足、Bean 被覆盖、配置项错误</td></tr><tr><td>面试一句话</td><td>管依赖组合</td><td>管默认装配</td></tr></tbody></table><p>面试被追问“Starter 为什么能开箱即用”时，要把两层说全：一方面 Starter 使相关类进入 classpath，另一方面 Boot 的自动配置类检测到这些类和配置条件后才注册默认 Bean。如果只说“引入 Starter 就自动创建对象”，容易被继续追问“到底谁创建的”“在哪里声明的”“如何不让它创建”。</p><h3 id="_2-bom-版本管理的原理" tabindex="-1">2. BOM 版本管理的原理 <a class="header-anchor" href="#_2-bom-版本管理的原理" aria-label="Permalink to &quot;2\\. BOM 版本管理的原理&quot;">​</a></h3><p>Spring Boot 项目通常会继承 spring-boot-starter-parent，或者通过 dependencyManagement 引入 spring-boot-dependencies BOM。它的作用是集中管理 Spring 生态和常用第三方库版本，使项目在声明依赖时不用给每个库都写版本号。这样做的工程价值很大：减少版本冲突，避免 Spring、Jackson、Tomcat、Hibernate Validator、Micrometer 等库之间出现不兼容组合。</p><p>实际项目里并不是绝对不能覆盖版本，但要谨慎。覆盖版本会打破 Boot 已验证的依赖组合，可能导致运行时 NoSuchMethodError、ClassNotFoundException、序列化行为变化或自动配置条件变化。例如手动升级 Jackson 后，某些模块方法签名变了；手动替换 Servlet 容器版本后，Tomcat 自动配置能启动但运行期行为异常。面试中可以这样表达：Boot 的版本管理不是为了限制开发，而是为了让常见依赖形成经过验证的兼容基线，只有在安全漏洞修复、公司统一版本规范或特殊功能需要时才应显式覆盖，并且覆盖后要做回归测试。</p><table tabindex="0"><thead><tr><th>版本管理方式</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td>继承 spring-boot-starter-parent</td><td>同时获得依赖管理、插件管理、构建默认值</td><td>普通 Boot 应用最常见</td></tr><tr><td>引入 spring-boot-dependencies BOM</td><td>只接入依赖版本管理，不强制继承 parent</td><td>公司已有统一父 POM</td></tr><tr><td>手动指定单个依赖版本</td><td>灵活但风险更高</td><td>漏洞修复、兼容公司中间件、临时规避缺陷</td></tr></tbody></table><p>这块的追问通常是“为什么有些依赖不用写版本号”“Starter 和 parent 是什么关系”“能不能不用 parent”。回答时要区分：Starter 是依赖集合；parent/BOM 是版本管理；自动配置是运行时 Bean 装配。三者共同组成 Boot 的工程体验，但职责不同。</p><h3 id="_3-自定义-starter-的本质是把公司通用能力产品化" tabindex="-1">3. 自定义 Starter 的本质是把公司通用能力产品化 <a class="header-anchor" href="#_3-自定义-starter-的本质是把公司通用能力产品化" aria-label="Permalink to &quot;3\\. 自定义 Starter 的本质是把公司通用能力产品化&quot;">​</a></h3><p>公司内部经常会做自定义 Starter，例如统一日志链路、统一返回体、统一鉴权拦截器、统一 Redis 序列化、统一对象存储客户端、统一 MQ 生产者配置。自定义 Starter 的目标不是“炫技”，而是把跨项目重复配置沉淀成可复用依赖，让业务项目只需要引入依赖、写少量配置项就能接入公共能力。</p><p>一个较完整的自定义 Starter 通常包含三部分：第一，提供业务或基础设施相关的核心类；第二，提供自动配置类，根据条件创建默认 Bean；第三，在 META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports 中声明自动配置类，让 Boot 启动时能导入候选配置。早期 Boot 版本更多使用 META-INF/spring.factories，新版本主路径已经切到 .imports 文件。面试被问自定义 Starter 时，最好能说出这条链路，而不是只说“写一个配置类加几个注解”。</p><p>常见失败点也要知道：自动配置类没有写进 .imports，导致根本没有被加载；条件注解写得太严格，导致 classpath 或属性不满足；默认 Bean 没有使用 @ConditionalOnMissingBean，导致用户项目无法覆盖；配置属性类没有启用绑定，导致 application.yml 中的值没有注入；Starter 引入过重依赖，导致业务项目被迫带入不需要的组件。能讲这些边界，项目表达会比简单照抄开源 Starter 更可信。</p><h2 id="三、启动入口-springbootapplication-展开的三类职责" tabindex="-1">三、启动入口：@SpringBootApplication 展开的三类职责 <a class="header-anchor" href="#三、启动入口-springbootapplication-展开的三类职责" aria-label="Permalink to &quot;三、启动入口：@SpringBootApplication 展开的三类职责&quot;">​</a></h2><h3 id="_1-springapplication-run-不只是调用-main-方法" tabindex="-1">1. SpringApplication.run 不只是调用 main 方法 <a class="header-anchor" href="#_1-springapplication-run-不只是调用-main-方法" aria-label="Permalink to &quot;1\\. SpringApplication.run 不只是调用 main 方法&quot;">​</a></h3><p>典型 Spring Boot 启动类如下：</p><p>@SpringBootApplication public class DemoApplication { public static void main(String[] args) { SpringApplication.run(DemoApplication.class, args); } }</p><p>main 方法看起来简单，但它背后会创建 SpringApplication，推断应用类型，准备环境，加载配置，创建 ApplicationContext，刷新容器，触发自动配置，启动内嵌 Web 容器，发布应用事件，最后调用启动后 Runner。不同版本细节会变化，但整体主线可以这样记：准备环境和配置源 -&gt; 创建容器 -&gt; 加载 BeanDefinition -&gt; 执行自动配置和条件判断 -&gt; 刷新容器创建单例 Bean -&gt; Web 场景启动内嵌容器 -&gt; 发布启动完成事件 -&gt; 执行 Runner。</p><p>这条启动链路在面试里不要求背每一行源码，但要能把关键阶段说出来。尤其要强调：自动配置不是在 main 方法里手动 new 出来的，而是在容器解析配置类、处理 @Import、加载自动配置候选类、判断条件后完成的。这样回答可以自然过渡到 AutoConfigurationImportSelector。</p><h3 id="_2-springbootapplication-的三个核心注解分别管什么" tabindex="-1">2. @SpringBootApplication 的三个核心注解分别管什么 <a class="header-anchor" href="#_2-springbootapplication-的三个核心注解分别管什么" aria-label="Permalink to &quot;2\\. @SpringBootApplication 的三个核心注解分别管什么&quot;">​</a></h3><p>@SpringBootApplication 是组合注解，核心可以拆成三块：</p><p>@SpringBootConfiguration @EnableAutoConfiguration @ComponentScan public @interface SpringBootApplication { }</p><p>@SpringBootConfiguration 本质上是配置类语义，可以看作特殊的 @Configuration。它说明启动类可以参与 Spring 容器的配置解析，允许在启动类或其导入配置中声明 Bean。</p><p>@ComponentScan 负责业务组件扫描，默认扫描启动类所在包及其子包。因此启动类一般放在项目根包下，例如 com.example.order.OrderApplication，让 controller、service、repository、config 等子包都能被扫描到。如果启动类放得太深，就可能出现 Controller 访问 404、Service 注入失败、Repository 没有注册等问题。这个问题常被包装成“为什么我的接口没生效”“为什么组件没注入进来”，本质是扫描边界错误。</p><p>@EnableAutoConfiguration 是自动配置入口。它通过 @Import 导入选择器，由选择器读取自动配置候选类，再由条件注解决定哪些配置类真正生效。这里要分清：@ComponentScan 扫描的是项目中的业务组件，@EnableAutoConfiguration 导入的是 Boot 和第三方 Starter 提供的自动配置类。一个管“你写的组件”，一个管“框架提供的默认配置”。</p><h3 id="_3-扫描边界、排除自动配置和启动类位置是高频失效点" tabindex="-1">3. 扫描边界、排除自动配置和启动类位置是高频失效点 <a class="header-anchor" href="#_3-扫描边界、排除自动配置和启动类位置是高频失效点" aria-label="Permalink to &quot;3\\. 扫描边界、排除自动配置和启动类位置是高频失效点&quot;">​</a></h3><p>扫描边界最常见的错误是启动类没有放在根包。解决方式有三种：第一，把启动类移动到根包，这是最推荐的方式；第二，在 @SpringBootApplication(scanBasePackages = &quot;...&quot;) 中显式指定扫描包；第三，使用 @ComponentScan 指定范围。但如果不是多模块或特殊包结构，不建议过度配置扫描路径，因为扫描范围太大会拖慢启动，也可能把不该进入当前应用的 Bean 扫进来。</p><p>排除自动配置有两类写法：注解排除和配置文件排除。注解上可以使用：</p><p>@SpringBootApplication(exclude = DataSourceAutoConfiguration.class) public class DemoApplication { }</p><p>配置文件中可以使用：</p><p>spring: autoconfigure: exclude: - org.springframework.boot.autoconfigure.jdbc.DataSourceAutoConfiguration</p><p>典型场景是项目暂时不需要数据库，但 classpath 中引入了数据库相关依赖，Boot 尝试创建 DataSource 却找不到 URL、用户名、驱动等配置，导致启动失败。面试里如果被问“为什么启动时报 Failed to configure a DataSource”，不要只说“配置数据库地址”，还要补充：如果这个应用本来不需要数据库，可以排除 DataSourceAutoConfiguration；如果需要数据库，则应该补齐数据源配置或检查 profile 是否激活。</p><h3 id="_4-启动类的配置边界" tabindex="-1">4. 启动类的配置边界 <a class="header-anchor" href="#_4-启动类的配置边界" aria-label="Permalink to &quot;4\\. 启动类的配置边界&quot;">​</a></h3><p>很多新手会把各种 @Bean、@EnableScheduling、@EnableAsync、@MapperScan、拦截器配置都塞进启动类。小项目可以跑，但维护性差。更合理的做法是：启动类只保留应用入口和少量全局启用注解；Web、数据源、缓存、线程池、安全、序列化等配置拆到独立 config 包；业务组件放在业务包；跨项目通用配置沉淀为 Starter。</p><p>面试项目表达可以这样说：我们项目启动类保持很薄，只作为 Boot 应用入口；业务组件依赖默认扫描；MyBatis 扫描、线程池、序列化、全局异常等配置拆到独立配置类；对于公司统一日志和鉴权逻辑，则通过内部 Starter 接入。这样能体现你对工程结构有基本边界感。</p><h2 id="四、自动配置源码链路-从-importselector-到默认-bean" tabindex="-1">四、自动配置源码链路：从 ImportSelector 到默认 Bean <a class="header-anchor" href="#四、自动配置源码链路-从-importselector-到默认-bean" aria-label="Permalink to &quot;四、自动配置源码链路：从 ImportSelector 到默认 Bean&quot;">​</a></h2><h3 id="_1-autoconfigurationimportselector-是自动配置候选类进入容器的关键入口" tabindex="-1">1. AutoConfigurationImportSelector 是自动配置候选类进入容器的关键入口 <a class="header-anchor" href="#_1-autoconfigurationimportselector-是自动配置候选类进入容器的关键入口" aria-label="Permalink to &quot;1\\. AutoConfigurationImportSelector 是自动配置候选类进入容器的关键入口&quot;">​</a></h3><p>自动配置的核心链路可以概括为：@SpringBootApplication -&gt; @EnableAutoConfiguration -&gt; @Import(AutoConfigurationImportSelector.class) -&gt; 读取自动配置候选类 -&gt; 过滤和排序 -&gt; 条件注解判断 -&gt; 注册满足条件的 Bean。</p><p><img src="'+i+'" alt="images/02-springboot-autoconfig-chain.png"></p><p>images/02-springboot-autoconfig-chain.png</p><p>AutoConfigurationImportSelector 实现了 ImportSelector 相关机制。ImportSelector 的作用是在配置类解析阶段返回一批需要导入的配置类全限定名。也就是说，自动配置类并不是被组件扫描扫出来的，而是通过 @Import 选择器导入的。这个区别非常重要：你自己写的 @Service 依赖 @ComponentScan；Boot 预置的自动配置类依赖自动配置导入机制。</p><p>在较新的 Spring Boot 版本中，自动配置候选类主要声明在：</p><p>META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports</p><p>早期版本常见入口是：</p><p>META-INF/spring.factories</p><p>历史上很多资料会说“Spring Boot 读取 spring.factories 实现自动配置”，这个说法对旧版本是主路径，但新版本要补充 .imports。面试里可以这样答：Boot 早期通过 spring.factories 加载 EnableAutoConfiguration 候选类，后续版本将自动配置类声明迁移到 .imports 文件，目的是让自动配置导入更轻量、更明确；但无论文件位置如何变化，本质都是框架维护一批候选自动配置类，再通过条件注解决定是否生效。</p><h3 id="_2-条件注解的自动配置筛选原理" tabindex="-1">2. 条件注解的自动配置筛选原理 <a class="header-anchor" href="#_2-条件注解的自动配置筛选原理" aria-label="Permalink to &quot;2\\. 条件注解的自动配置筛选原理&quot;">​</a></h3><p>自动配置类如果全部无条件生效，应用会变得不可控。Boot 通过 @Conditional 体系控制装配边界，常见条件包括 classpath、Bean、属性、Web 类型、资源、单例候选等。</p><table tabindex="0"><thead><tr><th>条件注解</th><th>判断依据</th><th>典型含义</th></tr></thead><tbody><tr><td>@ConditionalOnClass</td><td>classpath 是否存在指定类</td><td>引入相关依赖后，该能力才可能启用</td></tr><tr><td>@ConditionalOnMissingClass</td><td>classpath 是否不存在指定类</td><td>避免和某些实现冲突</td></tr><tr><td>@ConditionalOnBean</td><td>容器中是否已有指定 Bean</td><td>依赖前置组件存在后再装配</td></tr><tr><td>@ConditionalOnMissingBean</td><td>容器中是否缺少指定 Bean</td><td>用户没自定义时，框架才创建默认 Bean</td></tr><tr><td>@ConditionalOnProperty</td><td>配置属性是否满足条件</td><td>用配置项控制功能开关</td></tr><tr><td>@ConditionalOnWebApplication</td><td>当前是否 Web 应用</td><td>区分 Servlet、Reactive 或非 Web 场景</td></tr><tr><td>@ConditionalOnResource</td><td>指定资源是否存在</td><td>根据配置文件或资源存在性启用能力</td></tr></tbody></table><p>条件注解的重点不是背名字，而是理解它们解决了什么问题。@ConditionalOnClass 解决“依赖在不在”；@ConditionalOnProperty 解决“开关开没开”；@ConditionalOnMissingBean 解决“用户是否接管”；@ConditionalOnWebApplication 解决“当前场景对不对”。如果某个自动配置没有生效，排查也要沿着这几个维度走。</p><p>例如引入 Redis Starter 后，如果 RedisTemplate 没有按预期出现，要检查 Redis 相关类是否进入 classpath，Redis 自动配置类是否被排除，连接工厂是否创建成功，是否已有用户自定义的 RedisTemplate 或 RedisConnectionFactory，配置属性是否绑定成功。这个思路比“重启一下”“删掉依赖试试”更像真实工程排查。</p><h3 id="_3-配置属性绑定让自动配置从配置文件读取参数" tabindex="-1">3. 配置属性绑定让自动配置从配置文件读取参数 <a class="header-anchor" href="#_3-配置属性绑定让自动配置从配置文件读取参数" aria-label="Permalink to &quot;3\\. 配置属性绑定让自动配置从配置文件读取参数&quot;">​</a></h3><p>自动配置不只是创建 Bean，还要把配置文件中的参数绑定到配置属性类。Boot 中大量自动配置都配合 @ConfigurationProperties 使用，例如服务器端口、数据源连接池、Jackson 序列化、Redis、线程池、文件上传、Actuator 端点等。</p><p>@ConfigurationProperties 的价值是把一组相关配置绑定到类型安全的 Java 对象，支持宽松绑定、类型转换、默认值和校验。比如 server.port、server.servlet.context-path 会绑定到服务器相关属性对象；spring.datasource.url、spring.datasource.username 会绑定到数据源属性对象；自动配置类再读取这些属性对象创建对应 Bean。</p><p>这解释了一个常见问题：为什么配置项写错不会像 Java 编译错误一样立刻报错？因为配置绑定发生在运行时，如果没有启用严格绑定或配置元数据提示，拼错 key 可能只是导致属性没有被绑定，进而使用默认值或在后续创建 Bean 时失败。因此项目里推荐使用 IDE 能识别的配置元数据、@ConfigurationProperties 配合校验注解、启动时配置校验和必要的集成测试，避免生产环境才发现配置没有生效。</p><h3 id="_4-用户-bean-覆盖默认配置是-boot-可扩展性的核心" tabindex="-1">4. 用户 Bean 覆盖默认配置是 Boot 可扩展性的核心 <a class="header-anchor" href="#_4-用户-bean-覆盖默认配置是-boot-可扩展性的核心" aria-label="Permalink to &quot;4\\. 用户 Bean 覆盖默认配置是 Boot 可扩展性的核心&quot;">​</a></h3><p>Boot 的自动配置遵循一个重要原则：默认配置应该能被用户覆盖。常见实现方式就是自动配置类在声明默认 Bean 时加 @ConditionalOnMissingBean。如果容器中已经存在用户定义的同类型 Bean 或指定名称 Bean，默认 Bean 就不会创建。</p><p>以 JSON 序列化为例，Boot 可以自动配置 ObjectMapper 和消息转换器。如果项目定义了自己的 ObjectMapper，用于配置时间格式、空值处理、枚举序列化、Long 转字符串等，那么默认配置可能被跳过或被用户配置增强。以 Web MVC 为例，如果项目实现了 WebMvcConfigurer，可以添加拦截器、格式化器、跨域规则、静态资源映射；但如果使用 @EnableWebMvc，会全面接管 Spring MVC 默认配置，导致 Boot 的很多 MVC 自动配置退场。这个边界经常被面试追问。</p><p>覆盖默认配置也有风险。第一，同类型 Bean 多个候选可能导致注入歧义，需要 @Primary 或 @Qualifier。第二，自定义 Bean 名称或类型不匹配时，可能没有覆盖到目标默认 Bean。第三，过度使用 @EnableWebMvc、手动注册 DispatcherServlet、手动配置消息转换器，可能破坏 Boot 默认行为。面试回答要体现“默认可覆盖，但覆盖要知道条件和影响面”。</p><h2 id="五、外部化配置、profile-与配置中心的覆盖原理" tabindex="-1">五、外部化配置、Profile 与配置中心的覆盖原理 <a class="header-anchor" href="#五、外部化配置、profile-与配置中心的覆盖原理" aria-label="Permalink to &quot;五、外部化配置、Profile 与配置中心的覆盖原理&quot;">​</a></h2><h3 id="_1-environment-的配置聚合模型" tabindex="-1">1. Environment 的配置聚合模型 <a class="header-anchor" href="#_1-environment-的配置聚合模型" aria-label="Permalink to &quot;1\\. Environment 的配置聚合模型&quot;">​</a></h3><p>Spring Boot 支持多种配置源：application.properties、application.yml、profile 文件、环境变量、系统属性、命令行参数、测试配置、配置中心、容器平台注入的变量等。应用运行时读取到的最终值来自 Spring 的 Environment，它由多个 PropertySource 叠加而成。后加入或高优先级的来源可以覆盖低优先级来源。</p><p><img src="'+p+'" alt="images/02-springboot-config-priority.png"></p><p>images/02-springboot-config-priority.png</p><p>因此排查配置问题时，不能只盯着 application.yml。如果本地文件写的是 server.port: 8080，但启动命令传了 --server.port=9090，最终端口会是 9090；如果生产环境通过环境变量 SERVER_PORT=8081 注入，也可能覆盖文件中的值；如果接入 Nacos、Apollo、Spring Cloud Config 等配置中心，远端配置还可能在启动阶段或刷新阶段覆盖本地配置。</p><p>面试中可以把配置优先级说成一个原则：离运行实例越近、越明确的配置通常优先级越高。命令行参数比打包进 JAR 的配置更靠近本次启动；环境变量比代码仓库里的默认值更贴近部署环境；配置中心比本地默认文件更便于运维动态管理。具体顺序要以所用 Boot 和 Spring Cloud 版本为准，但排查思路始终是看最终 Environment，再定位来源。</p><h3 id="_2-profile-的环境隔离边界" tabindex="-1">2. Profile 的环境隔离边界 <a class="header-anchor" href="#_2-profile-的环境隔离边界" aria-label="Permalink to &quot;2\\. Profile 的环境隔离边界&quot;">​</a></h3><p>Profile 用来区分不同运行环境或功能组合。例如通用配置写在 application.yml，开发环境写在 application-dev.yml，生产环境写在 application-prod.yml。启动时通过 spring.profiles.active=prod 激活生产配置，Boot 会把通用配置和对应 profile 配置合并，后者覆盖前者同名 key。</p><p>常见写法包括：</p><p>spring: profiles: active: dev</p><p>或者启动命令中指定：</p><p>java -jar app.jar --spring.profiles.active=prod</p><p>Profile 的误区有两个。第一，不要把敏感密钥长期写在仓库里的 profile 文件中，生产密码、AK/SK、数据库账号更适合由环境变量、密钥管理系统或配置中心注入。第二，不要把 profile 当权限控制。激活 prod 只是加载生产配置，不代表用户权限、接口权限或数据隔离自动成立。面试里可以补充：profile 是配置隔离机制，不是安全机制。</p><h3 id="_3-环境变量、命令行和容器部署要关注命名转换" tabindex="-1">3. 环境变量、命令行和容器部署要关注命名转换 <a class="header-anchor" href="#_3-环境变量、命令行和容器部署要关注命名转换" aria-label="Permalink to &quot;3\\. 环境变量、命令行和容器部署要关注命名转换&quot;">​</a></h3><p>在 Linux、Docker、Kubernetes 环境中，配置经常通过环境变量注入。Boot 支持宽松绑定，例如 SERVER_PORT 可以映射到 server.port，SPRING_DATASOURCE_URL 可以映射到 spring.datasource.url。这让容器部署很方便，但也带来一个排查点：环境变量命名、大小写、下划线转换、数组或复杂对象绑定如果写错，应用可能读取不到预期值。</p><p>命令行参数适合本次启动临时覆盖，例如临时修改端口、日志级别、profile。它的优点是明确，缺点是容易散落在启动脚本、进程管理平台或容器编排文件中。生产环境排查配置时，应该同时看应用包内配置、启动命令、环境变量、配置中心、运维平台注入项，而不是只看代码仓库。</p><p>如果面试官问“为什么本地能跑，服务器配置不生效”，可以沿着这条链路回答：先确认激活的 profile，再确认配置源优先级，再看环境变量或命令行是否覆盖，再看配置中心是否下发了同名 key，最后通过 Actuator 的 /actuator/env 或启动日志确认最终值来源。生产环境暴露 /actuator/env 要做权限控制，不能直接公网开放。</p><h3 id="_4-配置中心接入后要关注启动时配置和动态刷新边界" tabindex="-1">4. 配置中心接入后要关注启动时配置和动态刷新边界 <a class="header-anchor" href="#_4-配置中心接入后要关注启动时配置和动态刷新边界" aria-label="Permalink to &quot;4\\. 配置中心接入后要关注启动时配置和动态刷新边界&quot;">​</a></h3><p>配置中心的作用是把配置从应用包中移到统一平台，便于多环境管理、灰度发布、动态调整和审计。常见方案有 Nacos、Apollo、Spring Cloud Config 等。接入后要区分两类配置：启动时必须确定的配置，以及运行期可以动态刷新的配置。</p><p>启动时必须确定的配置包括应用名、注册中心地址、配置中心地址、基础数据源、日志初始化、端口等关键参数。这些配置如果加载太晚，应用可能已经启动失败。运行期可刷新配置包括部分业务开关、限流阈值、降级策略、提示文案、非核心超时时间等。即使框架支持动态刷新，也不代表所有 Bean 都适合热更新，例如连接池、线程池、序列化器、核心安全策略随意刷新可能造成不一致。</p><p>项目表达可以这样说：我们把环境差异配置放在配置中心，本地文件只保留默认值和必要启动参数；生产环境通过命名空间、分组或 profile 区分；敏感配置走独立密钥管理；动态刷新只用于业务开关和部分阈值，线程池、数据源等核心资源调整需要评估并配合发布。这个说法比“我们用了 Nacos 配置中心”更能体现工程意识。</p><h2 id="六、内嵌-servlet-容器启动流程-tomcat-如何被创建并接管请求" tabindex="-1">六、内嵌 Servlet 容器启动流程：Tomcat 如何被创建并接管请求 <a class="header-anchor" href="#六、内嵌-servlet-容器启动流程-tomcat-如何被创建并接管请求" aria-label="Permalink to &quot;六、内嵌 Servlet 容器启动流程：Tomcat 如何被创建并接管请求&quot;">​</a></h2><h3 id="_1-从外部-tomcat-到内嵌-tomcat-部署单元发生变化" tabindex="-1">1. 从外部 Tomcat 到内嵌 Tomcat，部署单元发生变化 <a class="header-anchor" href="#_1-从外部-tomcat-到内嵌-tomcat-部署单元发生变化" aria-label="Permalink to &quot;1\\. 从外部 Tomcat 到内嵌 Tomcat，部署单元发生变化&quot;">​</a></h3><p>传统 Java Web 应用通常打成 WAR 包，部署到外部 Tomcat。Tomcat 先启动，再加载 Web 应用，应用依赖外部容器提供 Servlet 运行环境。Spring Boot 更常见的方式是打成可执行 JAR，应用进程启动时创建内嵌 Tomcat、Jetty 或 Undertow，并把 Spring MVC 的 DispatcherServlet 注册到容器中。</p><p>这个变化的工程意义很清楚：部署单元从“一个外部容器里挂多个应用”变成“一个应用就是一个独立进程”；应用版本和容器版本绑定在构建产物中，减少服务器环境差异；容器化部署时也更自然，一个镜像运行一个应用进程。面试中要强调这不是 Tomcat 消失了，而是 Tomcat 从外部运行环境变成了应用依赖和启动流程的一部分。</p><p>默认情况下，spring-boot-starter-web 会引入 spring-boot-starter-tomcat。如果要切换 Jetty 或 Undertow，需要排除默认 Tomcat，再引入目标容器 Starter。切换容器不是常规项目必做项，面试里重点是理解 Servlet 容器由谁创建、何时启动、如何注册 MVC 入口。</p><h3 id="_2-web-应用启动的大致链路" tabindex="-1">2. Web 应用启动的大致链路 <a class="header-anchor" href="#_2-web-应用启动的大致链路" aria-label="Permalink to &quot;2\\. Web 应用启动的大致链路&quot;">​</a></h3><p>在 Servlet Web 应用中，Boot 会创建 ServletWebServerApplicationContext 这类 Web 容器上下文。容器刷新过程中，会通过 ServletWebServerFactory 创建具体 WebServer。默认 Tomcat 场景下，对应工厂通常是 TomcatServletWebServerFactory，它负责创建、配置并启动内嵌 Tomcat。</p><p>简化链路可以这样记：SpringApplication.run 创建 Web 类型 ApplicationContext -&gt; 刷新容器 -&gt; 找到 ServletWebServerFactory -&gt; 创建 WebServer -&gt; 初始化内嵌 Tomcat -&gt; 注册 DispatcherServlet、Filter、Listener、ServletContextInitializer -&gt; 绑定端口并启动 -&gt; 请求进入 Tomcat 后交给 Spring MVC 分发。</p><p>DispatcherServlet 是 Spring MVC 的前端控制器。请求到达后，它根据 HandlerMapping 找到 Controller 方法，再通过 HandlerAdapter 调用方法，完成参数绑定、校验、消息转换、返回体写出和异常处理。Boot 对 Web 层的默认配置，本质上是在这条 MVC 链路周围补齐常用组件。</p><h3 id="_3-端口、上下文路径和端口冲突是常见启动问题" tabindex="-1">3. 端口、上下文路径和端口冲突是常见启动问题 <a class="header-anchor" href="#_3-端口、上下文路径和端口冲突是常见启动问题" aria-label="Permalink to &quot;3\\. 端口、上下文路径和端口冲突是常见启动问题&quot;">​</a></h3><p>端口由 server.port 控制，默认通常是 8080。上下文路径由 server.servlet.context-path 控制，例如配置为 /api 后，原本 /users 接口会变成 /api/users。这两个配置经常导致“接口访问不到”：有时不是 Controller 没注册，而是端口或上下文路径访问错了。</p><p>端口冲突是另一类高频问题。启动时报端口被占用时，要先确认当前应用实际读取到的 server.port，再查找占用该端口的进程。开发环境可以临时改端口或停止占用进程；生产环境要检查服务编排、实例数量、宿主机端口映射和探针配置。容器环境中还要区分容器内部端口和宿主机映射端口，不要把 server.port 和 Kubernetes Service 端口混为一谈。</p><p>如果项目启动很慢或 Web 容器启动后接口 404，也要沿链路排查：Controller 是否被扫描到，请求路径是否包含 context-path，HTTP 方法是否匹配，是否有网关或反向代理路径重写，是否有安全框架拦截，/actuator/mappings 中是否能看到对应映射。这样比只看 Controller 代码更完整。</p><h3 id="_4-war-部署仍然存在-但要理解启动方式差异" tabindex="-1">4. WAR 部署仍然存在，但要理解启动方式差异 <a class="header-anchor" href="#_4-war-部署仍然存在-但要理解启动方式差异" aria-label="Permalink to &quot;4\\. WAR 部署仍然存在，但要理解启动方式差异&quot;">​</a></h3><p>Spring Boot 也支持打 WAR 包部署到外部 Servlet 容器。此时通常需要继承 SpringBootServletInitializer 并重写 configure 方法，让外部容器能够初始化 Spring 应用。JAR 和 WAR 的区别不在业务代码，而在谁启动谁：可执行 JAR 是应用启动内嵌容器；WAR 是外部容器启动应用。</p><p>多数微服务和普通后端项目更推荐可执行 JAR，因为部署一致性更好。但在一些传统企业环境中，统一外部容器、统一运维规范或遗留系统集成仍然可能要求 WAR。面试里可以说：Boot 默认推荐可执行 JAR 和内嵌容器，但不是不能部署 WAR；选择取决于运维体系和系统架构。</p><h2 id="七、rest-接口工程化-参数绑定、校验、异常与返回体规范" tabindex="-1">七、REST 接口工程化：参数绑定、校验、异常与返回体规范 <a class="header-anchor" href="#七、rest-接口工程化-参数绑定、校验、异常与返回体规范" aria-label="Permalink to &quot;七、REST 接口工程化：参数绑定、校验、异常与返回体规范&quot;">​</a></h2><h3 id="_1-spring-boot-web-开发本质仍然是-spring-mvc" tabindex="-1">1. Spring Boot Web 开发本质仍然是 Spring MVC <a class="header-anchor" href="#_1-spring-boot-web-开发本质仍然是-spring-mvc" aria-label="Permalink to &quot;1\\. Spring Boot Web 开发本质仍然是 Spring MVC&quot;">​</a></h3><p>Spring Boot 并没有发明一套新的 Web MVC，它是在 Spring MVC 之上提供默认配置。常见注解要按职责记，而不是机械背列表。</p><table tabindex="0"><thead><tr><th>注解</th><th>职责</th><th>常见追问</th></tr></thead><tbody><tr><td>@RestController</td><td>组合 @Controller 和 @ResponseBody，返回值写入响应体</td><td>与 @Controller 的区别</td></tr><tr><td>@RequestMapping</td><td>定义通用请求映射</td><td>类级路径和方法级路径如何拼接</td></tr><tr><td>@GetMapping / @PostMapping</td><td>按 HTTP 方法映射</td><td>GET 和 POST 语义区别</td></tr><tr><td>@RequestParam</td><td>绑定 query 或表单参数</td><td>必填、默认值、类型转换</td></tr><tr><td>@PathVariable</td><td>绑定路径变量</td><td>REST 风格资源 ID</td></tr><tr><td>@RequestBody</td><td>绑定 JSON 请求体</td><td>依赖消息转换器，通常一个方法一个 body</td></tr><tr><td>@RequestHeader</td><td>读取请求头</td><td>Token、租户、客户端版本</td></tr><tr><td>@Validated / @Valid</td><td>触发校验</td><td>嵌套校验、分组校验、方法参数校验</td></tr></tbody></table><p>REST 接口的核心不是注解越多越好，而是资源语义、参数来源和响应规范清楚。GET 更适合查询，POST 常用于创建资源或提交动作，PUT 常表示整体更新，PATCH 表示局部更新，DELETE 表示删除。实际项目中也会因为网关、权限、幂等、安全审计等因素调整设计，但至少要能说明方法语义和接口边界。</p><h3 id="_2-参数绑定要区分-query、path、body、header" tabindex="-1">2. 参数绑定要区分 query、path、body、header <a class="header-anchor" href="#_2-参数绑定要区分-query、path、body、header" aria-label="Permalink to &quot;2\\. 参数绑定要区分 query、path、body、header&quot;">​</a></h3><p>参数绑定是很多接口问题的根源。@RequestParam 读取 URL query 参数或表单参数，例如 /users?page=1&amp;size=10；@PathVariable 读取路径变量，例如 /users/{id}；@RequestBody 通过 HttpMessageConverter 把 JSON 请求体反序列化为 Java 对象；@RequestHeader 读取请求头，例如鉴权 Token、traceId、租户 ID。</p><p>常见错误包括：GET 请求把复杂 JSON 放在 body 中，导致网关或客户端兼容性问题；一个方法声明多个 @RequestBody，但 HTTP 请求本质上只有一个 body；字段类型不匹配导致反序列化失败；前端传空字符串而后端用数字类型接收；日期格式没有统一；Long 类型 ID 返回给前端后出现精度丢失。项目里通常会通过 DTO、统一日期格式、统一 Jackson 配置、Long 转字符串策略、参数校验和异常处理来解决。</p><p>面试项目表达可以这样说：我们的 Controller 不直接使用数据库实体接收请求，而是定义请求 DTO 和响应 VO；路径 ID 用 @PathVariable，分页过滤条件用 @RequestParam 或查询 DTO，复杂提交用 @RequestBody；进入业务层前先完成绑定和校验，避免脏数据进入 Service。</p><h3 id="_3-后端参数校验的边界责任" tabindex="-1">3. 后端参数校验的边界责任 <a class="header-anchor" href="#_3-后端参数校验的边界责任" aria-label="Permalink to &quot;3\\. 后端参数校验的边界责任&quot;">​</a></h3><p>后端接口不能完全依赖前端校验，因为浏览器页面、移动端、小程序、脚本、第三方系统都可能直接调用接口。Spring Boot 项目通常引入 spring-boot-starter-validation，在 DTO 字段上声明约束，再在 Controller 参数上加 @Valid 或 @Validated 触发校验。</p><p><img src="'+d+'" alt="images/02-springboot-validation-exception.png"></p><p>images/02-springboot-validation-exception.png</p><p>常见约束要分清：@NotNull 只要求对象不为 null；@NotBlank 面向字符串，要求去掉空白后仍有内容；@NotEmpty 常用于字符串、集合、数组，要求长度或大小不为 0；@Size 控制长度或集合大小；@Min、@Max 控制数值边界；@Email 校验邮箱格式；@Pattern 使用正则表达式。嵌套对象要配合 @Valid 才会继续校验内部字段，分组校验可以解决新增和更新规则不同的问题。</p><p>校验失败后，Spring MVC 会抛出绑定或方法参数校验相关异常。成熟项目不会在每个 Controller 里写重复 try-catch，而是通过 @RestControllerAdvice 统一捕获，转换为统一错误码、错误消息和字段级错误信息。这样前端处理稳定，接口文档也更清晰。</p><h3 id="_4-统一异常和返回体规范体现接口治理能力" tabindex="-1">4. 统一异常和返回体规范体现接口治理能力 <a class="header-anchor" href="#_4-统一异常和返回体规范体现接口治理能力" aria-label="Permalink to &quot;4\\. 统一异常和返回体规范体现接口治理能力&quot;">​</a></h3><p>全局异常处理的常见写法如下：</p><p>@RestControllerAdvice public class GlobalExceptionHandler {</p><p>@ExceptionHandler(BusinessException.class) public CommonResult&lt;?&gt; handleBusiness(BusinessException ex) { return CommonResult.error(ex.getCode(), ex.getMessage()); } }</p><p>这段代码的重点不是模板，而是职责边界。Controller 负责接收请求和返回结果，DTO 负责承载参数和校验规则，Service 负责业务判断并在必要时抛出业务异常，全局异常处理器负责把参数异常、业务异常、系统异常转换成统一响应结构。参数异常通常返回字段级错误信息；业务异常返回明确业务错误码，例如库存不足、用户不存在、权限不足；系统异常要记录完整日志，对外返回通用提示，避免泄露堆栈、SQL、服务器路径等内部信息。</p><p>统一返回体常见结构包括 code、message、data、traceId、timestamp 等。是否所有接口都必须包一层返回体，要看团队规范和网关体系；但在典型后台管理、移动端 API、中台接口中，统一响应能降低前端处理成本，也便于错误码治理。面试里不要只说“我用了全局异常”，要补充错误分类、日志记录、traceId、字段校验信息和系统异常脱敏。</p><h2 id="八、启动扩展点-在正确生命周期做正确的事" tabindex="-1">八、启动扩展点：在正确生命周期做正确的事 <a class="header-anchor" href="#八、启动扩展点-在正确生命周期做正确的事" aria-label="Permalink to &quot;八、启动扩展点：在正确生命周期做正确的事&quot;">​</a></h2><h3 id="_1-runner-适合容器启动后执行一次性逻辑" tabindex="-1">1. Runner 适合容器启动后执行一次性逻辑 <a class="header-anchor" href="#_1-runner-适合容器启动后执行一次性逻辑" aria-label="Permalink to &quot;1\\. Runner 适合容器启动后执行一次性逻辑&quot;">​</a></h3><p>CommandLineRunner 和 ApplicationRunner 都会在 Spring 容器启动完成后执行，适合做启动校验、缓存预热、字典加载、任务注册、轻量初始化等逻辑。区别在于参数形式不同：CommandLineRunner 接收原始字符串数组，ApplicationRunner 接收封装后的 ApplicationArguments，更方便解析选项参数。</p><p>需要注意的是，Runner 会影响应用启动完成时间。如果在 Runner 中执行耗时很长、依赖外部系统、失败概率高的任务，应用可能长时间处于启动中，甚至因为初始化失败而无法上线。生产项目中，启动阶段应该只做必要校验和可控初始化；大批量数据修复、远程同步、复杂预热更适合拆到后台任务、运维脚本或异步流程中。</p><p>如果有多个 Runner，可以使用 @Order 控制顺序。面试可以说：我们用 Runner 做必要的启动校验，例如检查关键配置是否存在、加载本地缓存或注册定时任务，但不会把长事务、大批量同步、依赖外部服务强一致的逻辑放进启动链路。</p><h3 id="_2-applicationevent-和-applicationlistener-适合解耦生命周期动作" tabindex="-1">2. ApplicationEvent 和 ApplicationListener 适合解耦生命周期动作 <a class="header-anchor" href="#_2-applicationevent-和-applicationlistener-适合解耦生命周期动作" aria-label="Permalink to &quot;2\\. ApplicationEvent 和 ApplicationListener 适合解耦生命周期动作&quot;">​</a></h3><p>Spring 应用启动过程中会发布多个事件，例如环境准备、上下文准备、容器刷新完成、应用启动完成、应用就绪、启动失败等。业务项目也可以定义自己的事件，用 ApplicationEventPublisher 发布，再通过 ApplicationListener 或 @EventListener 监听。</p><p>事件机制适合做解耦：订单创建后发布订单事件，积分、通知、审计等模块各自监听；应用就绪后发布预热事件，多个模块分别处理自己的预热逻辑。但事件不是消息队列。默认情况下，同进程事件的可靠性、持久化、跨服务传递、失败重试都不如 MQ。需要跨服务可靠投递时，应该使用消息中间件，而不是把 Spring 事件当分布式事件总线。</p><p>启动事件的追问常见是：“ApplicationRunner 和监听 ApplicationReadyEvent 有什么区别？”可以回答：Runner 是 Boot 约定的启动后回调，适合直接执行一次性逻辑；ApplicationReadyEvent 表示应用已经准备好接收请求，更偏生命周期事件监听；二者都在启动后阶段，但表达模型不同，事件更适合多个模块解耦监听。</p><h3 id="_3-initializingbean、-postconstruct-和-bean-生命周期边界" tabindex="-1">3. InitializingBean、@PostConstruct 和 Bean 生命周期边界 <a class="header-anchor" href="#_3-initializingbean、-postconstruct-和-bean-生命周期边界" aria-label="Permalink to &quot;3\\. InitializingBean、@PostConstruct 和 Bean 生命周期边界&quot;">​</a></h3><p>@PostConstruct 和 InitializingBean.afterPropertiesSet() 都发生在 Bean 创建、依赖注入之后，用于 Bean 自身初始化。它们和 Runner 的区别在于生命周期位置不同：Bean 初始化发生在容器刷新过程中，Runner 发生在应用上下文启动完成后。简单说，前者是“某个 Bean 准备好时”，后者是“整个应用准备好后”。</p><p>在 Bean 初始化方法里可以做本对象内部资源准备，例如构建本地缓存、校验必要属性、初始化客户端轻量状态。但不要做依赖整个应用已启动的逻辑，也不要在这里发起大量远程调用。因为此时其他 Bean 或 Web 容器状态可能还没完全就绪，失败还会直接影响容器刷新。</p><p>面试中可以用一张对比表来回答：</p><table tabindex="0"><thead><tr><th>扩展点</th><th>执行时机</th><th>适合做什么</th><th>不适合做什么</th></tr></thead><tbody><tr><td>@PostConstruct</td><td>单个 Bean 属性注入后</td><td>校验属性、初始化轻量资源</td><td>依赖整个应用可用的流程</td></tr><tr><td>InitializingBean</td><td>Bean 初始化阶段</td><td>框架式初始化、强约束校验</td><td>大量业务任务</td></tr><tr><td>ApplicationRunner</td><td>容器启动完成后</td><td>启动校验、缓存预热</td><td>长时间阻塞任务</td></tr><tr><td>CommandLineRunner</td><td>容器启动完成后</td><td>使用原始启动参数</td><td>复杂参数解析</td></tr><tr><td>ApplicationListener</td><td>指定事件发布时</td><td>生命周期解耦、模块监听</td><td>分布式可靠消息</td></tr></tbody></table><h3 id="_4-扩展点选择要看失败影响面" tabindex="-1">4. 扩展点选择要看失败影响面 <a class="header-anchor" href="#_4-扩展点选择要看失败影响面" aria-label="Permalink to &quot;4\\. 扩展点选择要看失败影响面&quot;">​</a></h3><p>扩展点最重要的不是“会几个接口”，而是知道失败影响面。@PostConstruct 失败通常会导致 Bean 创建失败，进而应用启动失败；Runner 失败也可能导致启动失败；事件监听如果同步执行，异常也可能影响发布流程；异步监听虽然能降低阻塞，但要处理线程池、异常日志和失败补偿。</p><p>项目里可以按重要程度区分：关键配置缺失、核心依赖不可用，可以让启动失败，避免带病上线；缓存预热失败、非核心字典加载失败，可以记录告警并允许应用继续启动，后续通过懒加载或后台重试补偿；依赖第三方系统的初始化，最好设置超时和降级，避免启动过程被外部服务拖死。能讲清这些取舍，比简单背生命周期顺序更有面试价值。</p><h2 id="九、定时、异步、线程池与-actuator-启动之后的运行治理" tabindex="-1">九、定时、异步、线程池与 Actuator：启动之后的运行治理 <a class="header-anchor" href="#九、定时、异步、线程池与-actuator-启动之后的运行治理" aria-label="Permalink to &quot;九、定时、异步、线程池与 Actuator：启动之后的运行治理&quot;">​</a></h2><h3 id="_1-定时任务适合轻量单机任务-分布式调度要另选方案" tabindex="-1">1. 定时任务适合轻量单机任务，分布式调度要另选方案 <a class="header-anchor" href="#_1-定时任务适合轻量单机任务-分布式调度要另选方案" aria-label="Permalink to &quot;1\\. 定时任务适合轻量单机任务，分布式调度要另选方案&quot;">​</a></h3><p>Spring Boot 中简单定时任务通常通过 @EnableScheduling 开启，再使用 @Scheduled 声明执行周期：</p><p>@Scheduled(cron = &quot;0 */5 * * * ?&quot;) public void refreshCache() { // 每 5 分钟刷新缓存 }</p><p>@Scheduled 适合单机、轻量、失败影响可控的任务，例如刷新本地缓存、清理临时文件、同步少量状态。它的边界也很明显：多实例部署时每个实例都会执行，容易重复处理；缺少完善的任务分片、失败重试、可视化管理、执行记录和告警；任务耗时超过周期时还要关注并发执行和线程池配置。因此对于需要分布式调度、分片执行、失败重试、人工触发、执行日志的场景，更适合使用 XXL-JOB、ElasticJob、Quartz 或公司统一调度平台。</p><p>面试被问“定时任务怎么避免多实例重复执行”时，不能只说“加锁”。要进一步说明方案选择：轻量场景可以使用 Redis 分布式锁或数据库锁保证同一时刻只有一个实例执行；任务治理要求高时用调度平台，由调度中心负责路由、分片、重试和记录；任务本身还要设计幂等，避免锁失效或重试导致数据重复。</p><h3 id="_2-async-的代理链路与线程池原理" tabindex="-1">2. @Async 的代理链路与线程池原理 <a class="header-anchor" href="#_2-async-的代理链路与线程池原理" aria-label="Permalink to &quot;2\\. @Async 的代理链路与线程池原理&quot;">​</a></h3><p>异步任务通常通过 @EnableAsync 和 @Async 实现。它适合把非核心、可延迟的工作从主链路拆出去，例如发送通知、写操作日志、生成报表、异步回调第三方接口。核心要点有三个：第一，@Async 依赖 Spring 代理，同类内部方法调用可能绕过代理导致不生效；第二，必须显式配置线程池，避免使用不可控默认执行器；第三，异步异常不会像同步调用一样直接抛给调用方，必须记录日志、告警或做补偿。</p><p>线程池配置要关注核心线程数、最大线程数、队列容量、线程存活时间、拒绝策略、线程名前缀和异常处理。队列过大可能导致请求堆积和延迟不可控；最大线程数过大可能打爆下游或耗尽 CPU；拒绝策略如果使用默认抛异常，需要调用方能感知；如果使用丢弃策略，必须确认业务允许丢弃。面试回答可以结合项目：我们把邮件、短信、日志补偿放入独立异步线程池，线程名前缀便于日志检索，拒绝时记录告警并降级，不和主业务线程池混用。</p><h3 id="_3-actuator-是线上排查入口-但生产暴露要克制" tabindex="-1">3. Actuator 是线上排查入口，但生产暴露要克制 <a class="header-anchor" href="#_3-actuator-是线上排查入口-但生产暴露要克制" aria-label="Permalink to &quot;3\\. Actuator 是线上排查入口，但生产暴露要克制&quot;">​</a></h3><p>Actuator 提供运行时观测端点，常见包括 /actuator/health、/actuator/metrics、/actuator/env、/actuator/beans、/actuator/mappings、/actuator/loggers、/actuator/threaddump 等。它可以帮助排查应用是否存活、依赖健康状态、指标趋势、配置最终值、Bean 是否创建、接口映射是否存在、日志级别是否需要临时调整。</p><p>线上排查自动配置问题时，可以结合几类信息：启动日志和条件评估报告看哪些自动配置匹配或未匹配；beans 看目标 Bean 是否存在；env 看配置值来自哪里；mappings 看接口是否注册；metrics 看请求、线程、JVM、连接池指标；health 看数据库、Redis、磁盘等依赖状态。这样排查才能从“感觉配置没生效”变成“定位哪一个条件不满足”。</p><p>生产环境必须控制 Actuator 暴露范围。通常只开放 health、info 给探针或网关，其余端点放在内网、管理端口或加认证授权。env、beans、threaddump、heapdump 等端点可能泄露敏感配置、内部类名、线程栈甚至内存数据，绝不能无保护暴露公网。面试里主动提安全边界，会显得更接近真实生产经验。</p><h3 id="_4-健康检查要区分存活、就绪和依赖状态" tabindex="-1">4. 健康检查要区分存活、就绪和依赖状态 <a class="header-anchor" href="#_4-健康检查要区分存活、就绪和依赖状态" aria-label="Permalink to &quot;4\\. 健康检查要区分存活、就绪和依赖状态&quot;">​</a></h3><p>健康检查不是简单返回 “UP”。在容器化和微服务环境中，通常要区分 liveness 和 readiness。liveness 表示进程是否还活着，如果失败，平台可能重启容器；readiness 表示应用是否准备好接收流量，如果失败，平台应该暂时摘除流量但不一定重启。数据库、Redis、MQ、磁盘、配置中心等依赖也可能纳入健康检查，但要控制检查成本和超时时间。</p><p>如果把所有外部依赖都强绑定到 liveness，一旦某个下游短暂抖动，应用可能被平台频繁重启，造成雪崩。更合理的做法是：进程级存活检查保持轻量；就绪检查反映当前实例是否适合接流量；关键依赖失败要影响 readiness 或触发降级，而不是一律重启。这个细节经常出现在生产排查和系统设计追问中。</p><h2 id="十、高频追问、排查路线与项目表达模板" tabindex="-1">十、高频追问、排查路线与项目表达模板 <a class="header-anchor" href="#十、高频追问、排查路线与项目表达模板" aria-label="Permalink to &quot;十、高频追问、排查路线与项目表达模板&quot;">​</a></h2><h3 id="_1-高频面试追问表" tabindex="-1">1. 高频面试追问表 <a class="header-anchor" href="#_1-高频面试追问表" aria-label="Permalink to &quot;1\\. 高频面试追问表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>回答骨架</th><th>继续追问时补充</th></tr></thead><tbody><tr><td>Spring Boot 和 Spring 有什么区别</td><td>Spring Framework 提供 IoC、AOP、事务、MVC 等能力；Boot 基于 Spring 做工程化封装，简化依赖、配置、启动、部署和观测</td><td>Boot 不替代 Spring，Boot 应用底层仍然是 Spring 容器</td></tr><tr><td>Starter 和自动配置有什么区别</td><td>Starter 管依赖聚合和版本，自动配置管默认 Bean 注册</td><td>Starter 让类进入 classpath，自动配置根据条件创建 Bean</td></tr><tr><td>@SpringBootApplication 包含什么</td><td>@SpringBootConfiguration、@EnableAutoConfiguration、@ComponentScan</td><td>分别对应配置类语义、自动配置入口、组件扫描</td></tr><tr><td>Controller 扫描不到怎么办</td><td>检查启动类是否在根包，扫描路径是否覆盖 Controller 包</td><td>可用 scanBasePackages，但更推荐调整包结构</td></tr><tr><td>自动配置如何实现</td><td>@EnableAutoConfiguration 通过 AutoConfigurationImportSelector 导入候选自动配置类，再由条件注解决定是否生效</td><td>新版本使用 .imports，旧版本常见 spring.factories</td></tr><tr><td>为什么自定义 Bean 后默认 Bean 不见了</td><td>很多默认 Bean 使用 @ConditionalOnMissingBean，用户声明后默认配置退让</td><td>检查 Bean 类型、名称、@Primary、@Qualifier</td></tr><tr><td>配置文件为什么不生效</td><td>可能被 profile、环境变量、命令行、配置中心或更高优先级来源覆盖</td><td>看最终 Environment，必要时用 Actuator env</td></tr><tr><td>Boot 内嵌 Tomcat 怎么启动</td><td>Web 上下文刷新时通过 ServletWebServerFactory 创建并启动 Tomcat，注册 DispatcherServlet</td><td>默认来自 Web Starter，可切换 Jetty/Undertow</td></tr><tr><td>端口冲突怎么排查</td><td>确认最终 server.port，查占用进程或容器端口映射</td><td>区分应用端口、宿主机映射、网关路径</td></tr><tr><td>参数校验怎么做</td><td>引入 validation，DTO 上写约束，Controller 参数加 @Valid 或 @Validated</td><td>嵌套校验、分组校验、全局异常处理</td></tr><tr><td>全局异常怎么设计</td><td>@RestControllerAdvice 捕获参数、业务、系统异常，统一返回错误码和消息</td><td>系统异常日志完整、对外脱敏、带 traceId</td></tr><tr><td>@Async 为什么不生效</td><td>未开启异步、方法不是 Spring Bean 调用、同类内部调用绕过代理、方法不可代理</td><td>还要检查线程池和异常处理</td></tr><tr><td>@Scheduled 多实例重复执行怎么办</td><td>轻量场景加分布式锁，高要求场景用调度平台</td><td>任务要幂等，锁和重试都不是绝对可靠</td></tr><tr><td>Actuator 有什么用</td><td>提供健康、指标、配置、Bean、映射、日志等观测端点</td><td>生产只开放必要端点并加权限</td></tr></tbody></table><h3 id="_2-自动配置失效的排查路线" tabindex="-1">2. 自动配置失效的排查路线 <a class="header-anchor" href="#_2-自动配置失效的排查路线" aria-label="Permalink to &quot;2\\. 自动配置失效的排查路线&quot;">​</a></h3><p>自动配置失效时，不要一开始就改代码。建议按固定路线排查：第一，看依赖是否进入 classpath，如果没有相关类，@ConditionalOnClass 肯定不满足；第二，看自动配置类是否被排除，可能在启动类或配置文件中写了 exclude；第三，看配置属性是否满足条件，特别是 enabled 开关、profile、配置中心覆盖；第四，看容器中是否已经有用户自定义 Bean，导致 @ConditionalOnMissingBean 的默认 Bean 跳过；第五，看应用类型是否匹配，例如非 Web 应用不会启用 Web MVC 自动配置；第六，看版本是否兼容，依赖冲突可能让条件判断或 Bean 创建失败。</p><p>可以把这条路线变成面试回答：“我会先看依赖树确认 Starter 和核心类是否存在，再看条件评估报告或启动日志确认自动配置是否匹配，然后看配置最终值是否被覆盖，再看容器里是否已有同类型 Bean，最后结合 Actuator 的 beans、env、mappings 定位 Bean、配置或接口映射问题。”这类回答比“我会看日志”更有层次。</p><h3 id="_3-项目表达模板-把-boot-讲成一条工程链路" tabindex="-1">3. 项目表达模板：把 Boot 讲成一条工程链路 <a class="header-anchor" href="#_3-项目表达模板-把-boot-讲成一条工程链路" aria-label="Permalink to &quot;3\\. 项目表达模板：把 Boot 讲成一条工程链路&quot;">​</a></h3><p>如果面试要求结合项目介绍 Spring Boot，可以使用下面这类表达：</p><p>我们项目基于 Spring Boot 构建，底层还是使用 Spring 的 IoC、事务和 MVC。Boot 主要帮我们解决工程启动和默认装配问题。比如 Web 场景通过 spring-boot-starter-web 引入 MVC、Jackson 和内嵌 Tomcat，启动时自动配置根据 classpath 和配置属性创建消息转换器、DispatcherServlet、错误处理和静态资源相关组件。业务上我们保留默认配置的同时，也自定义了统一 Jackson 时间格式、全局异常处理、参数校验和统一返回体。配置方面，本地、测试、生产通过 profile 和配置中心隔离，关键配置最终以 Environment 为准。上线后通过 Actuator、日志、traceId 和指标排查健康、接口映射、配置覆盖和 Bean 装配问题。</p><p>如果被追问“你们有没有自定义自动配置或 Starter”，可以继续说：</p><p>公司内部通用能力会封装成 Starter，比如统一鉴权、日志追踪、Redis 序列化或对象存储客户端。Starter 负责引入依赖和自动配置类，自动配置类通过 .imports 声明，内部用 @ConditionalOnClass、@ConditionalOnProperty、@ConditionalOnMissingBean 控制是否创建默认 Bean。业务项目如果需要调整，可以通过配置项或声明自己的 Bean 覆盖默认行为。</p><p>如果被追问“线上出问题怎么排查”，可以继续说：</p><p>我会先确认问题属于启动失败、接口映射、配置覆盖还是 Bean 装配。启动失败看异常栈和条件评估报告；接口访问不到看 context-path、HTTP 方法、网关路径和 /actuator/mappings；配置不对看 profile、环境变量、命令行、配置中心和 /actuator/env；Bean 没创建看依赖是否进入 classpath、条件注解是否满足、是否已有用户 Bean 覆盖。排查过程中生产端点要有权限控制，敏感信息不能暴露公网。</p><h3 id="_4-最后复习标准" tabindex="-1">4. 最后复习标准 <a class="header-anchor" href="#_4-最后复习标准" aria-label="Permalink to &quot;4\\. 最后复习标准&quot;">​</a></h3><p>这一章复习到位的标准不是能背出所有注解，而是能把 Spring Boot 讲成一条完整链路：引入 Starter 后依赖进入 classpath；@SpringBootApplication 打开组件扫描和自动配置；AutoConfigurationImportSelector 导入候选自动配置类；条件注解根据 classpath、配置属性、已有 Bean 和运行环境筛选；配置属性绑定把外部配置注入默认组件；用户自定义 Bean 或配置项覆盖默认行为；Web 场景由内嵌 Tomcat 启动并注册 DispatcherServlet；请求进入后完成参数绑定、校验、业务处理、异常转换和统一响应；运行期通过定时、异步、线程池、Actuator、日志和指标治理。</p><p>P0 必须掌握 Spring Boot 与 Spring Framework 的边界、Starter 与自动配置区别、@SpringBootApplication 三个核心注解、自动配置源码入口、条件注解、配置优先级和用户 Bean 覆盖。P1 要能结合 Web 项目讲内嵌 Tomcat、REST 参数绑定、校验、全局异常、统一返回体。P2 再补充 Runner、事件、Bean 生命周期、定时任务、异步线程池、Actuator、健康检查和线上排查。面试时沿这条主线回答，大多数 Spring Boot 追问都能接住。</p>',187)])])}const B=a(l,[["render",s]]);export{m as __pageData,B as default};
